function calculateCart(items, voucher) {
  if (!Array.isArray(items) || items.length === 0) return { subtotal: 0, discount: 0, vat: 0, total: 0 };
  let subtotal = 0;
  for (const item of items) {
    if (item.price < 0 || item.quantity < 0) throw new Error('Invalid item values');
    subtotal += item.price * item.quantity;
  }
  let discount = 0;
  if (voucher && voucher.code === 'VIP20') {
    discount = Math.min(subtotal, subtotal * 0.2);
  }
  const vat = Math.max(0, subtotal - discount) * 0.1;
  return {
    subtotal: Math.round(subtotal),
    discount: Math.round(discount),
    vat: Math.round(vat),
    total: Math.round(subtotal - discount + vat)
  };
}
